INSERT INTO mail_templates(template_key,name,subject_template,html_template,status) VALUES
('verification','邮箱验证','验证你的 {{site_name}} 邮箱','<p class="muted">账户安全</p><h1>验证邮箱</h1><p>你好，{{display_name}}。</p><p>欢迎使用 {{site_name}}。完成邮箱验证后，即可继续使用工作区、链接和分享功能。</p><p><a class="button" href="{{verification_url}}">完成邮箱验证</a></p><p class="muted">如果你没有注册 {{site_name}}，可以忽略这封邮件。验证按钮无法使用时，请返回登录页重新发送验证邮件。</p>','active'),
('account_welcome','账户欢迎','欢迎使用 {{site_name}}','<p class="muted">账户已就绪</p><h1>欢迎来到 {{site_name}}</h1><p>你好，{{display_name}}。</p><p>你的账户已经创建完成。现在可以创建短链接、二维码、文件分享和工作区，并在同一处查看访问数据。</p><p><a class="button" href="{{console_url}}">进入工作区</a></p>','active'),
('password_reset','重置密码','重置你的 {{site_name}} 登录密码','<p class="muted">账户安全</p><h1>重置登录密码</h1><p>我们收到了你的密码重置请求。</p><p><a class="button" href="{{reset_url}}">设置新密码</a></p><p class="muted">此操作链接将在 {{expires_minutes}} 分钟后失效。如果不是你发起的请求，请不要点击按钮。</p>','active'),
('password_changed','密码已修改','你的 {{site_name}} 密码已修改','<p class="muted">安全通知</p><h1>登录密码已修改</h1><p>你的账户密码已于 {{changed_at}} 完成修改，旧登录会话会按安全策略失效。</p><p class="muted">如果这不是你的操作，请立即联系支持团队。</p>','active'),
('email_changed','邮箱已修改','你的 {{site_name}} 登录邮箱已修改','<p class="muted">安全通知</p><h1>登录邮箱已修改</h1><p>账户登录邮箱已从 <strong>{{old_email}}</strong> 修改为 <strong>{{new_email}}</strong>。</p><p class="muted">操作时间：{{changed_at}}。如果这不是你的操作，请立即联系支持团队。</p>','active'),
('workspace_invitation','工作区邀请','{{inviter}} 邀请你加入 {{workspace_name}}','<p class="muted">团队协作</p><h1>你收到一个工作区邀请</h1><p><strong>{{inviter}}</strong> 邀请你以“{{role_name}}”身份加入工作区“{{workspace_name}}”。</p><p><a class="button" href="{{invitation_url}}">查看工作区邀请</a></p><p class="muted">邀请有效期至 {{expires_at}}。</p>','active'),
('workspace_role_changed','工作区角色变更','你在 {{workspace_name}} 的角色已更新','<p class="muted">团队协作</p><h1>工作区权限已更新</h1><p>你在“{{workspace_name}}”中的角色已调整为“{{new_role}}”。</p><p class="muted">操作人：{{actor}}</p>','active'),
('workspace_owner_transferred','工作区所有者变更','{{workspace_name}} 的所有者已变更','<p class="muted">团队协作</p><h1>工作区所有者已变更</h1><p>“{{workspace_name}}”的所有权已由 <strong>{{old_owner}}</strong> 转移给 <strong>{{new_owner}}</strong>。</p><p class="muted">操作时间：{{changed_at}}</p>','active'),
('workspace_member_removed','已退出工作区','你已离开 {{workspace_name}}','<p class="muted">团队协作</p><h1>工作区成员状态已更新</h1><p>你已不再是工作区“{{workspace_name}}”的成员，之后将无法继续访问该工作区资源。</p>','active'),
('invoice_created','新账单','账单 {{invoice_number}} 已生成','<p class="muted">账单通知</p><h1>新账单已生成</h1><p>工作区：<strong>{{workspace_name}}</strong></p><p>套餐：{{plan_name}} · {{period_days}} 天</p><p>应付金额：<strong>{{settlement_amount}} {{settlement_currency}}</strong></p><p>{{fx_detail}}</p><p class="muted">支付期限：{{due_at}}</p><p><a class="button" href="{{billing_url}}">查看并支付账单</a></p>','active'),
('invoice_due_soon','账单即将到期','账单 {{invoice_number}} 即将到期','<p class="muted">账单提醒</p><h1>账单即将到期</h1><p>账单 <strong>{{invoice_number}}</strong> 将于 {{due_at}} 到期。</p><p>待支付：<strong>{{settlement_amount}} {{settlement_currency}}</strong></p><p><a class="button" href="{{billing_url}}">查看账单</a></p>','active'),
('invoice_overdue','账单已逾期','账单 {{invoice_number}} 已逾期','<p class="muted">账单提醒</p><h1>账单已逾期</h1><p>账单 <strong>{{invoice_number}}</strong> 已超过付款期限。</p><p>待支付：<strong>{{settlement_amount}} {{settlement_currency}}</strong></p><p><a class="button" href="{{billing_url}}">处理账单</a></p>','active'),
('invoice_paid','账单已支付','账单 {{invoice_number}} 已支付','<p class="muted">付款确认</p><h1>付款已确认</h1><p>账单 <strong>{{invoice_number}}</strong> 已完成支付，相关套餐状态会自动更新。</p><p>实付：<strong>{{settlement_amount}} {{settlement_currency}}</strong></p><p>支付方式：{{payment_provider}}</p><p>支付参考号：{{payment_reference}}</p><p>服务周期：{{period_start}} 至 {{period_end}}</p><p><a class="button" href="{{invoice_pdf_url}}">下载账单 PDF</a></p>','active'),
('invoice_voided','账单已作废','账单 {{invoice_number}} 已作废','<p class="muted">账单通知</p><h1>账单已作废</h1><p>账单 <strong>{{invoice_number}}</strong> 已作废，无需继续付款。</p><p>处理说明：{{note}}</p>','active'),
('payment_started','付款已创建','账单 {{invoice_number}} 的付款已创建','<p class="muted">付款处理中</p><h1>付款订单已创建</h1><p>账单：<strong>{{invoice_number}}</strong></p><p>支付方式：{{payment_provider}}</p><p>应付金额：<strong>{{settlement_amount}} {{settlement_currency}}</strong></p><p class="muted">商户订单号：{{merchant_order}}。请以支付渠道最终通知为准，不要重复付款。</p>','active'),
('payment_failed','付款失败','账单 {{invoice_number}} 付款未完成','<p class="muted">付款状态</p><h1>付款未完成</h1><p>账单 <strong>{{invoice_number}}</strong> 的 {{payment_provider}} 付款没有成功完成。</p><p>金额：{{settlement_amount}} {{settlement_currency}}</p><p>原因：{{failure_reason}}</p><p><a class="button" href="{{billing_url}}">返回账单中心</a></p>','active'),
('payment_refunded','付款已退款','账单 {{invoice_number}} 的款项已退款','<p class="muted">退款通知</p><h1>退款已处理</h1><p>账单：<strong>{{invoice_number}}</strong></p><p>退款金额：<strong>{{settlement_amount}} {{settlement_currency}}</strong></p><p>支付方式：{{payment_provider}}</p><p>参考号：{{payment_reference}}</p>','active'),
('subscription_changed','订阅已变更','{{workspace_name}} 的套餐已变更','<p class="muted">套餐状态</p><h1>套餐变更完成</h1><p>工作区“{{workspace_name}}”当前套餐为 <strong>{{plan_name}}</strong>。</p><p>服务周期：{{period_start}} 至 {{period_end}}</p>','active'),
('subscription_renewed','订阅已续期','{{workspace_name}} 已续费成功','<p class="muted">套餐状态</p><h1>续费成功</h1><p>工作区“{{workspace_name}}”的 <strong>{{plan_name}}</strong> 套餐已续费。</p><p>新的服务周期截止至 {{period_end}}。</p>','active'),
('subscription_cancellation_scheduled','已安排取消订阅','{{workspace_name}} 将在周期结束后停止续费','<p class="muted">套餐状态</p><h1>已安排周期结束后停止续费</h1><p>工作区“{{workspace_name}}”将在 {{period_end}} 当前周期结束后停止套餐服务。</p><p class="muted">在周期结束前仍可恢复续费。</p>','active'),
('subscription_cancellation_revoked','已撤销取消订阅','{{workspace_name}} 已恢复续费','<p class="muted">套餐状态</p><h1>已恢复续费</h1><p>工作区“{{workspace_name}}”已撤销周期结束停止计划，当前套餐将继续保持。</p>','active'),
('subscription_expiring','订阅即将结束','{{workspace_name}} 的服务周期即将结束','<p class="muted">套餐提醒</p><h1>服务周期即将结束</h1><p>工作区“{{workspace_name}}”当前服务周期将在 {{period_end}} 结束。</p><p><a class="button" href="{{billing_url}}">查看套餐与账单</a></p>','active'),
('subscription_cancelled','订阅已结束','{{workspace_name}} 的套餐服务已结束','<p class="muted">套餐状态</p><h1>订阅已结束</h1><p>工作区“{{workspace_name}}”的当前付费服务周期已经结束。</p><p><a class="button" href="{{billing_url}}">查看可用套餐</a></p>','active'),
('file_quarantined','文件安全提醒','文件 {{file_name}} 未通过安全检查','<p class="muted">安全通知</p><h1>文件未通过安全检查</h1><p>工作区：{{workspace_name}}</p><p>文件：<strong>{{file_name}}</strong></p><p>系统已阻止该文件开放下载。请前往文件安全中心查看检查结果或联系支持团队。</p>','active'),
('domain_verification_failed','域名验证失败','域名 {{domain_name}} 验证未通过','<p class="muted">域名状态</p><h1>域名验证未通过</h1><p>域名 <strong>{{domain_name}}</strong> 当前未能完成验证。</p><p>原因：{{reason}}</p><p><a class="button" href="{{domains_url}}">查看域名设置</a></p>','active'),
('support_ticket_created','工单已创建','[{{site_name}} #{{ticket_number}}] 我们已收到你的工单','<p class="muted">客户支持</p><h1>工单已创建</h1><p>你的工单 <strong>#{{ticket_number}}</strong> 已提交成功。</p><p>主题：{{subject}}</p><p class="muted">支持团队回复后会通过邮件通知你，请在客户中心查看完整会话。</p>','active'),
('support_ticket_reply','工单有新回复','[{{site_name}} #{{ticket_number}}] 工单有新回复','<p class="muted">客户支持</p><h1>工单有新回复</h1><p>你的工单 <strong>#{{ticket_number}}</strong> 收到新的支持回复。</p><p>主题：{{subject}}</p><p class="muted">请登录 {{site_name}} 客户中心查看完整会话并继续回复。</p>','active')
